// Cancellation and the request deadline cover the response body as well as its headers.
async function fetchJson<T>(url: string, options: JsonRequestOptions, measurement?: ReturnType<LoadTiming["request"]>): Promise<T> {
  const controller = new AbortController();
  const abort = () => controller.abort(options.signal?.reason);
  if (options.signal?.aborted) abort();
  else options.signal?.addEventListener("abort", abort, { once: true });
  const timeout = window.setTimeout(() => controller.abort(), options.timeoutMs ?? DEFAULT_JSON_TIMEOUT_MS);
  try {
    const response = await fetch(url, { cache: "no-store", signal: controller.signal, ...(measurement ? { headers: measurement.headers } : {}) });
    measurement?.response(response);
    if (!response.ok) throw new Error(response.status + " " + response.statusText);
    return await response.json() as T;
  } catch (error) {
    if (options.signal?.aborted) throw error;
    if (controller.signal.aborted) throw new Error("Request timed out. Retry the request.");
    throw error;
  } finally {
    window.clearTimeout(timeout);
    options.signal?.removeEventListener("abort", abort);
  }
}
